// Extrae el buffer del Excel recibido como binario o campo de formulario
// y prepara los parámetros para enviar al servidor.

const item = $input.first();

// El webhook con binaryData:true guarda archivos en $binary
// El campo se llama 'excelFile' (multipart form-data)
const binaryKey = Object.keys(item.binary || {}).find(
  k => k === 'excelFile' || k === 'data' || k.endsWith('.xlsx') || k.endsWith('.xls')
);

if (!binaryKey) {
  throw new Error(
    'No se encontró el archivo Excel. Envíe un archivo en el campo "excelFile" ' +
    '(multipart/form-data). Campos binarios disponibles: ' +
    JSON.stringify(Object.keys(item.binary || {}))
  );
}

const mime = item.binary[binaryKey].mimeType || 'application/octet-stream';
const fn   = item.binary[binaryKey].fileName  || 'entrada.xlsx';

return [{
  json: {
    binaryKey,
    mimeType:         mime,
    fileName:         fn,
    fechaAsignacion:  item.json.body?.fechaAsignacion || '',
    plantillaPath:    item.json.body?.plantillaPath   || '',
  },
  binary: item.binary,
}];

// Convierte el xlsxBase64 de la respuesta del servidor en un item binario
// para que el webhook pueda devolverlo como descarga.

const base64   = $json.xlsxBase64 || '';
const clientes = $json.clientes   || [];
const errores  = $json.errores    || [];

if (!base64) throw new Error('xlsxBase64 vacío en la respuesta del servidor');

const mimeType = 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet';
const fileName = `Plantilla_Singular_${new Date().toISOString().slice(0,10)}.xlsx`;

return [{
  json: {
    success:    true,
    totalFilas: $json.totalFilas,
    clientes:   clientes.length,
    errores:    errores.length,
    resumen: clientes.map(c =>
      `${c.cedula} | ${c.nombre} | ${c.cuantia} | ${c.vehiculos} veh. | ${c.correoJuzgado || 'sin correo'}`
    ).join('\n'),
    mimeType,
    fileName,
  },
  binary: {
    data: {
      data:     base64,
      mimeType,
      fileName,
    }
  }
}];
